function openSchedulerSetup(){const date=new Date(Date.now()+3600000);date.setMinutes(date.getMinutes()-date.getTimezoneOffset());$('schedulerKind').value='reminder';$('schedulerDueAt').value=date.toISOString().slice(0,16);$('schedulerTitle').value='';$('schedulerMessage').value='';$('schedulerRepeat').value='0';$('monitorTarget').value='ollama';$('monitorInterval').value='5';$('schedulerSetupStatus').textContent='';renderSchedulerKind();$('schedulerSetup').showModal();$('schedulerTitle').focus()}
