async function renderScheduledJobs(){const tree=$('projectTree');$('workspaceSectionTitle').textContent='Scheduled';$('newProjectBtn').hidden=false;$('newProjectBtn').title='Create reminder or monitor';$('newProjectBtn').onclick=openSchedulerSetup;$('openProjectsBtn').hidden=true;$('refreshProjectsBtn').onclick=renderScheduledJobs;try{const [state,monitorState]=await Promise.all([window.masterChief.listScheduledJobs(),window.masterChief.listMonitors()]);const reminderCards=state.jobs.map(job=>{const card=document.createElement('article');card.className=`project-node schedule-card status-${job.status}`;const title=document.createElement('strong');title.textContent=job.title;const message=document.createElement('span');message.className='project-file';message.textContent=job.message;const timing=document.createElement('small');timing.textContent=job.nextRunAt?`Next: ${new Date(job.nextRunAt).toLocaleString()}`:`${job.status} · Last: ${job.lastRunAt?new Date(job.lastRunAt).toLocaleString():'never'}`;const actions=document.createElement('div');actions.className='schedule-actions';if(job.status==='active')actions.append(schedulerActionButton(job,'Pause','pause'));if(job.status==='paused')actions.append(schedulerActionButton(job,'Resume','resume'));if(!['completed','cancelled'].includes(job.status))actions.append(schedulerActionButton(job,'Cancel','cancel'));const history=document.createElement('small');history.textContent=`Reminder · ${job.intervalMinutes?`every ${job.intervalMinutes} minutes · `:'one time · '}${job.history.length} event${job.history.length===1?'':'s'}`;card.append(title,message,timing,actions,history);return card});const monitorCards=monitorState.monitors.map(item=>{const card=document.createElement('article');card.className=`project-node schedule-card monitor-card status-${item.status}`;const title=document.createElement('strong');title.textContent=item.title;const stateLine=document.createElement('span');stateLine.className='project-file';stateLine.textContent=item.lastLabel||'Waiting for first local health check';const timing=document.createElement('small');timing.textContent=item.nextCheckAt?`Next check: ${new Date(item.nextCheckAt).toLocaleString()}`:item.status;const actions=document.createElement('div');actions.className='schedule-actions';if(item.status==='active')actions.append(monitorActionButton(item,'Pause','pause'));if(item.status==='paused')actions.append(monitorActionButton(item,'Resume','resume'));if(item.status!=='cancelled')actions.append(monitorActionButton(item,'Cancel','cancel'));const history=document.createElement('small');history.textContent=`Monitor · every ${item.intervalMinutes} minutes · quiet while unchanged · ${item.history.length} checks/events`;card.append(title,stateLine,timing,actions,history);return card});tree.replaceChildren(...monitorCards,...reminderCards);if(!monitorCards.length&&!reminderCards.length){const empty=document.createElement('p');empty.className='hint';empty.textContent='No local reminders or monitors yet. Select + to create one.';tree.append(empty)}}catch(e){tree.textContent=`Scheduled work unavailable: ${e.message}`}}
$('schedulerKind').onchange=renderSchedulerKind;$('schedulerCancelBtn').onclick=()=>$('schedulerSetup').close();$('schedulerSetupForm').onsubmit=async event=>{event.preventDefault();$('schedulerSetupStatus').textContent='Creating…';try{if($('schedulerKind').value==='monitor')await window.masterChief.createMonitor({target:$('monitorTarget').value,intervalMinutes:Number($('monitorInterval').value)});else await window.masterChief.createScheduledJob({title:$('schedulerTitle').value,message:$('schedulerMessage').value,dueAt:new Date($('schedulerDueAt').value).toISOString(),intervalMinutes:Number($('schedulerRepeat').value)});$('schedulerSetup').close();await renderScheduledJobs();activity('Local scheduled work created','success')}catch(e){$('schedulerSetupStatus').textContent=e.message}};
