function runtimeMetric(label,value,detail=''){const card=document.createElement('article');card.className='runtime-metric';const name=document.createElement('span');name.textContent=label;const data=document.createElement('strong');data.textContent=value;card.append(name,data);if(detail){const note=document.createElement('small');note.textContent=detail;card.append(note)}return card}
async function refreshRuntimeCenter(){const status=$('runtimeCenterStatus'),grid=$('runtimeCenterGrid'),list=$('runtimeCheckpointList');status.textContent='Checking the private worker…';grid.replaceChildren();list.replaceChildren();try{const r=await window.masterChief.getComfyUiRuntimeStatus();const device=r.devices[0];grid.append(runtimeMetric('Endpoint',r.endpoint,`${r.endpointHistory.length} verified endpoint${r.endpointHistory.length===1?'':'s'} retained`),runtimeMetric('Remote control',r.remote.label,r.remote.host?`${r.remote.user}@${r.remote.host}`:''),runtimeMetric('ComfyUI',r.system.comfyuiVersion,`${r.system.os} · Python ${r.system.pythonVersion}`),runtimeMetric('PyTorch',r.system.pytorchVersion),runtimeMetric('System RAM',`${formatBytes(r.system.ramFree)} free`,`${formatBytes(r.system.ramTotal)} total`),runtimeMetric('Queue',`${r.queue.running} running`,`${r.queue.pending} pending`),runtimeMetric('GPU',device?.name||'No device reported',device?`${formatBytes(device.vramFree)} free of ${formatBytes(device.vramTotal)}`:'Check worker configuration'));list.replaceChildren(...r.checkpoints.map(name=>{const chip=document.createElement('span');chip.textContent=name;return chip}));if(!r.checkpoints.length)list.textContent='No checkpoints reported.';status.textContent=`Verified ${new Date(r.checkedAt).toLocaleString()}`;activity('Runtime Center evidence refreshed','success')}catch(e){status.textContent=e.message;activity('Runtime Center could not reach the worker','error')}}
async function runOperationalReadiness(){const button=$('runtimeReadinessBtn'),list=$('runtimeReadinessList'),status=$('runtimeCenterStatus');button.disabled=true;button.textContent='Running local checks…';list.replaceChildren();try{const report=await window.masterChief.getOperationalReadiness();status.textContent=`${report.status} · ${report.score}/100 · gate ${report.gate}`;for(const item of report.checks){const card=document.createElement('article');card.className=`readiness-check ${item.state}`;const head=document.createElement('header'),title=document.createElement('strong'),state=document.createElement('span'),evidence=document.createElement('p');title.textContent=`${item.label} · ${item.weight} pts`;state.textContent=item.state;head.append(title,state);evidence.textContent=item.evidence;card.append(head,evidence);if(item.repair){const repair=document.createElement('p');repair.className='repair';repair.textContent=`Repair: ${item.repair}`;card.append(repair)}list.append(card)}activity(`Operational readiness ${report.status}: ${report.score}/100`,report.status==='READY'?'success':'error')}catch(e){status.textContent=e.message;list.textContent='Operational readiness could not complete.';activity('Operational readiness check failed','error')}finally{button.disabled=false;button.textContent='Run full readiness check'}}
async function controlRuntime(action,label){if(!confirm(`${label}? Active ComfyUI work will be checked before this runs.`))return;const status=$('runtimeCenterStatus');status.textContent=`${label}…`;for(const id of ['runtimeRestartBtn','gamingModeBtn','runtimeResumeBtn'])$(id).disabled=true;try{const result=await window.masterChief.controlComfyUiRuntime(action);status.textContent=`${label}: ${result.after.label}`;activity(`${label} completed: ${result.after.state}`,'success');if(action!=='gaming-stop')await refreshRuntimeCenter()}catch(e){status.textContent=e.message;activity(`${label} failed`,'error')}finally{for(const id of ['runtimeRestartBtn','gamingModeBtn','runtimeResumeBtn'])$(id).disabled=false}}
$('runtimeCenterBtn').onclick=()=>{$('runtimeCenter').showModal();refreshRuntimeCenter()};$('runtimeCenterCloseBtn').onclick=()=>$('runtimeCenter').close();$('runtimeRefreshBtn').onclick=refreshRuntimeCenter;$('runtimeOpenBtn').onclick=()=>window.masterChief.openComfyUiRuntime().catch(e=>$('runtimeCenterStatus').textContent=e.message);$('runtimeConfigureBtn').onclick=()=>{$('runtimeCenter').close();openConnectorSetup('comfyui')};
$('runtimeReadinessBtn').onclick=runOperationalReadiness;
$('runtimeRestartBtn').onclick=()=>controlRuntime('restart','Restart Windows AI worker');$('gamingModeBtn').onclick=()=>controlRuntime('gaming-stop','Stop AI worker for gaming');$('runtimeResumeBtn').onclick=()=>controlRuntime('gaming-resume','Resume Windows AI worker');

refreshConnectors();refreshMediaCatalog();refreshProjects();restoreCreativeWorkspace();setInterval(()=>{refreshConnectors();refreshMediaCatalog()},15000);

// Revision controls are intentionally stronger than the original conservative
// image-to-image defaults. The delegated click runs after each button's own
// handler, so the chosen strength is retained for the submitted revision.
chat.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.classList.contains('revise')&&activeCreativeSession)activeCreativeSession.strength=.84;if(button.classList.contains('revise-major')&&activeCreativeSession)activeCreativeSession.strength=.98});
new MutationObserver(()=>{document.querySelectorAll('.media-actions .revise').forEach(button=>{if(button.textContent!=='Revise (strong)')button.textContent='Revise (strong)';button.title='Strong edit with an 84% transformation'});document.querySelectorAll('.media-actions .revise-major').forEach(button=>{if(button.textContent!=='Rebuild from request')button.textContent='Rebuild from request';button.title='Near-total redraw with a 98% transformation'})}).observe(chat,{childList:true,subtree:true});
